 16→func setupCleanTestRepo(t *testing.T) (*git.Repository, plumbing.Hash) {
 17→	t.Helper()
 18→
 19→	dir := t.TempDir()
 20→	repo, err := git.PlainInit(dir, false)
 21→	if err != nil {
 22→		t.Fatalf("failed to init git repo: %v", err)
 23→	}
 24→
 25→	t.Chdir(dir)
 26→	paths.ClearRepoRootCache()
 27→
 28→	// Create initial commit
 29→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
 30→	obj := repo.Storer.NewEncodedObject()
 31→	if err := emptyTree.Encode(obj); err != nil {
 32→		t.Fatalf("failed to encode empty tree: %v", err)
 33→	}
 34→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
 35→	if err != nil {
 36→		t.Fatalf("failed to store empty tree: %v", err)
 37→	}
 38→
 39→	sig := object.Signature{Name: "test", Email: "test@test.com"}
 40→	commit := &object.Commit{
 41→		TreeHash:  emptyTreeHash,
 42→		Author:    sig,
 43→		Committer: sig,
 44→		Message:   "initial commit",
 45→	}
 46→	commitObj := repo.Storer.NewEncodedObject()
 47→	if err := commit.Encode(commitObj); err != nil {
 48→		t.Fatalf("failed to encode commit: %v", err)
 49→	}
 50→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
 51→	if err != nil {
 52→		t.Fatalf("failed to store commit: %v", err)
 53→	}
 54→
 55→	// Create HEAD and master references
 56→	headRef := plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.NewBranchReferenceName("master"))
 57→	if err := repo.Storer.SetReference(headRef); err != nil {
 58→		t.Fatalf("failed to set HEAD: %v", err)
 59→	}
 60→	masterRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("master"), commitHash)
 61→	if err := repo.Storer.SetReference(masterRef); err != nil {
 62→		t.Fatalf("failed to set master: %v", err)
 63→	}
 64→
 65→	return repo, commitHash
 66→}
