 83→func TestRunClean_PreviewMode(t *testing.T) {
 84→	repo, commitHash := setupCleanTestRepo(t)
 85→
 86→	// Create shadow branches
 87→	shadowBranches := []string{"entire/abc1234", "entire/def5678"}
 88→	for _, b := range shadowBranches {
 89→		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(b), commitHash)
 90→		if err := repo.Storer.SetReference(ref); err != nil {
 91→			t.Fatalf("failed to create branch %s: %v", b, err)
 92→		}
 93→	}
 94→
 95→	// Also create entire/checkpoints/v1 (should NOT be listed)
 96→	sessionsRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), commitHash)
 97→	if err := repo.Storer.SetReference(sessionsRef); err != nil {
 98→		t.Fatalf("failed to create %s: %v", paths.MetadataBranchName, err)
 99→	}
100→
101→	var stdout bytes.Buffer
102→	err := runClean(&stdout, false) // force=false
103→	if err != nil {
104→		t.Fatalf("runClean() error = %v", err)
105→	}
106→
107→	output := stdout.String()
108→
109→	// Should show preview header
110→	if !strings.Contains(output, "orphaned items") {
111→		t.Errorf("Expected 'orphaned items' in output, got: %s", output)
112→	}
113→
114→	// Should list the shadow branches
115→	if !strings.Contains(output, "entire/abc1234") {
116→		t.Errorf("Expected 'entire/abc1234' in output, got: %s", output)
117→	}
118→	if !strings.Contains(output, "entire/def5678") {
119→		t.Errorf("Expected 'entire/def5678' in output, got: %s", output)
120→	}
121→
122→	// Should NOT list entire/checkpoints/v1
123→	if strings.Contains(output, paths.MetadataBranchName) {
124→		t.Errorf("Should not list '%s', got: %s", paths.MetadataBranchName, output)
125→	}
126→
127→	// Should prompt to use --force
128→	if !strings.Contains(output, "--force") {
129→		t.Errorf("Expected '--force' prompt in output, got: %s", output)
130→	}
131→
132→	// Branches should still exist (preview mode doesn't delete)
133→	for _, b := range shadowBranches {
134→		refName := plumbing.NewBranchReferenceName(b)
135→		if _, err := repo.Reference(refName, true); err != nil {
136→			t.Errorf("Branch %s should still exist after preview", b)
137→		}
138→	}
139→}
