 91→	lines = append(lines, fmt.Sprintf("  %s (%d)",
 92→		titleStyle.Render("Active Sessions"),
 93→		len(m.states)))
 94→	lines = append(lines, "")
 95→
 96→	// Table header
 97→	header := fmt.Sprintf("  %-9s  %-18s  %-14s  %-12s  %-12s  %s",
 98→		labelStyle.Render("ID"),
 99→		labelStyle.Render("Phase"),
100→		labelStyle.Render("Agent"),
101→		labelStyle.Render("Started"),
102→		labelStyle.Render("Last Active"),
103→		labelStyle.Render("Prompt"),
104→	)
105→	lines = append(lines, header)
106→	lines = append(lines, "  "+dimStyle.Render(strings.Repeat("─", 80)))
107→
108→	for i, s := range m.states {
109→		shortID := s.SessionID
110→		if len(shortID) > 7 {
111→			shortID = shortID[:7]
112→		}
113→
114→		phase := renderPhase(s.Phase)
115→
116→		agentLabel := string(s.AgentType)
117→		if agentLabel == "" {
118→			agentLabel = "(unknown)"
119→		}
120→		agentLabel = truncate(agentLabel, 12)
121→
122→		started := timeAgo(s.StartedAt)
123→
124→		lastActive := "-"
125→		if s.LastInteractionTime != nil {
126→			lastActive = timeAgo(*s.LastInteractionTime)
127→		}
128→
129→		prompt := truncate(s.FirstPrompt, 30)
130→		if prompt == "" {
131→			prompt = dimStyle.Render("-")
132→		}
133→
134→		line := fmt.Sprintf("  %-9s  %-18s  %-14s  %-12s  %-12s  %s",
135→			shortID, phase, agentLabel, started, lastActive, prompt)
136→
137→		if i == m.cursor {
138→			line = selectedItemStyle.Render(line)
139→		}
140→
141→		lines = append(lines, line)
142→	}
143→
144→	// Scroll data lines, keeping header pinned
145→	headerLines := 4 // title + blank + header + separator
146→	maxVisible := height - headerLines
147→	if maxVisible < 1 {
148→		maxVisible = 1
149→	}
150→
151→	visibleStart := 0
152→	if m.cursor-visibleStart >= maxVisible {
153→		visibleStart = m.cursor - maxVisible + 1
154→	}
155→
156→	result := lines[:headerLines]
157→	dataLines := lines[headerLines:]
158→	end := visibleStart + maxVisible
159→	if end > len(dataLines) {
160→		end = len(dataLines)
161→	}
162→	if visibleStart < len(dataLines) {
163→		result = append(result, dataLines[visibleStart:end]...)
164→	}
165→
166→	return strings.Join(result, "\n")
167→}
