169→func (m activeModel) renderDetail(_ int, height int) string {
170→	s := m.states[m.cursor]
171→
172→	var lines []string
173→	lines = append(lines, titleStyle.Render("Session Detail"))
174→	lines = append(lines, "")
175→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Session ID:"), valueStyle.Render(s.SessionID)))
176→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Phase:"), renderPhase(s.Phase)))
177→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Agent:"), valueStyle.Render(string(s.AgentType))))
178→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Started:"), valueStyle.Render(s.StartedAt.Format("2006-01-02 15:04:05"))))
179→
180→	if s.LastInteractionTime != nil {
181→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Last Active:"), valueStyle.Render(s.LastInteractionTime.Format("2006-01-02 15:04:05"))))
182→	}
183→
184→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Base Commit:"), valueStyle.Render(truncate(s.BaseCommit, 12))))
185→	lines = append(lines, fmt.Sprintf("  %s  %d", labelStyle.Render("Step Count:"), s.StepCount))
186→
187→	if s.WorktreePath != "" {
188→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Worktree:"), valueStyle.Render(s.WorktreePath)))
189→	}
190→
191→	if s.FirstPrompt != "" {
192→		lines = append(lines, "")
193→		lines = append(lines, labelStyle.Render("  First Prompt:"))
194→		lines = append(lines, "  "+valueStyle.Render(s.FirstPrompt))
195→	}
196→
197→	if s.TokenUsage != nil {
198→		lines = append(lines, "")
199→		lines = append(lines, labelStyle.Render("  Token Usage:"))
200→		lines = append(lines, fmt.Sprintf("    Input:  %d", s.TokenUsage.InputTokens))
201→		lines = append(lines, fmt.Sprintf("    Output: %d", s.TokenUsage.OutputTokens))
202→	}
203→
204→	if len(s.FilesTouched) > 0 {
205→		lines = append(lines, "")
206→		lines = append(lines, fmt.Sprintf("  %s (%d files)", labelStyle.Render("Files Touched:"), len(s.FilesTouched)))
207→		for _, f := range s.FilesTouched {
208→			lines = append(lines, "    "+dimStyle.Render(f))
209→		}
210→	}
211→
212→	lines = append(lines, "")
213→	lines = append(lines, dimStyle.Render("  Press Esc to go back"))
214→
215→	// Apply scroll
216→	start := m.scrollPos
217→	end := start + height
218→	if end > len(lines) {
219→		end = len(lines)
220→	}
221→	if start >= len(lines) {
222→		start = max(0, len(lines)-1)
223→	}
224→
225→	return strings.Join(lines[start:end], "\n")
226→}
