228→func renderPhase(p session.Phase) string {
229→	switch p {
230→	case session.PhaseActive:
231→		return activePhaseStyle.Render("ACTIVE")
232→	case session.PhaseIdle:
233→		return idlePhaseStyle.Render("IDLE")
234→	case session.PhaseEnded:
235→		return endedPhaseStyle.Render("ENDED")
236→	default:
237→		return idlePhaseStyle.Render("IDLE")
238→	}
239→}
